command:
const MODULE_ID = "substances-and-paraphernalia";
const FLAG_SOURCE = "sourceSubstanceId";
if (!game.user.isGM) { ui.notifications.warn("GM only."); return; }
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) { ui.notifications.warn(game.i18n.localize("FISHUT.RemoveAddiction.NoActor")); return; }
// Tolerance lives in the actor's tolerance record; a tolerance effect, when a
// substance ships one, only shows it. List and clear both.
const record = actor.getFlag(MODULE_ID, "tolerance") ?? {};
const rows = [];
const seen = new Set();
for (const effect of actor.effects) {
  const sid = effect.flags?.[MODULE_ID]?.[FLAG_SOURCE] ?? null;
  const aeRole = effect.flags?.[MODULE_ID]?.aeRole ?? null;
  const legacy = aeRole == null && /tolerance/i.test(effect.name ?? "");
  if (aeRole !== "tolerance" && !legacy) continue;
  if (legacy) console.warn(`[${MODULE_ID}] Remove Tolerance: matched legacy AE "${effect.name}" by name substring (no aeRole flag).`);
  rows.push({ effect, sourceId: sid, count: Number(record[sid]?.count) || 0 });
  if (sid) seen.add(sid);
}
for (const [sid, entry] of Object.entries(record)) {
  if (!seen.has(sid)) rows.push({ effect: null, sourceId: sid, count: Number(entry?.count) || 0 });
}
if (rows.length === 0) { ui.notifications.info(game.i18n.format("FISHUT.RemoveTolerance.NoCandidates", { actor: actor.name })); return; }
const label = (r) => r.effect?.name ?? actor.items.get(r.sourceId)?.name ?? "(orphan flag)";
const body = `${game.i18n.format("FISHUT.RemoveTolerance.PreviewIntro", { actor: actor.name })}<ul style="list-style:none;padding-left:0;">${rows.map((r, i) => `<li><label><input type="checkbox" name="row-${i}" checked> ${game.i18n.format("FISHUT.RemoveTolerance.RowDetail", { name: label(r), sourceId: r.sourceId ?? "(none)", stacks: r.count })}</label></li>`).join("")}</ul>`;
const result = await foundry.applications.api.DialogV2.wait({
  window: { title: game.i18n.localize("FISHUT.RemoveTolerance.Title") },
  content: body,
  buttons: [
    { action: "confirm", label: game.i18n.localize("FISHUT.RemoveAddiction.Confirm"), default: true,
      callback: (event, button) => { const fd = new FormData(button.form); return rows.map((_, i) => fd.has(`row-${i}`)); } },
    { action: "cancel", label: game.i18n.localize("FISHUT.RemoveAddiction.Cancel"), default: false,
      callback: () => null }
  ],
  rejectClose: false, modal: true,
});
if (!Array.isArray(result)) return;
const chosen = rows.filter((_, i) => result[i]);
if (chosen.length === 0) return;
const withEffect = chosen.filter((r) => r.effect);
if (withEffect.length) await actor.deleteEmbeddedDocuments("ActiveEffect", withEffect.map((r) => r.effect.id), { fishutIntentional: true });
const clears = {};
for (const r of chosen) if (r.sourceId && r.sourceId in record) clears[`flags.${MODULE_ID}.tolerance.${r.sourceId}`] = new foundry.data.operators.ForcedDeletion();
if (Object.keys(clears).length) await actor.update(clears);
const log = { effects: withEffect.map((r) => r.effect.toObject()), tolerance: Object.fromEntries(chosen.filter((r) => r.sourceId in record).map((r) => [r.sourceId, record[r.sourceId]])) };
await ChatMessage.create({
  user: game.user.id,
  whisper: ChatMessage.getWhisperRecipients("GM").map((u) => u.id),
  content: `<details><summary>${game.i18n.localize("FISHUT.RemoveTolerance.LogTitle")}</summary><pre>${foundry.utils.escapeHTML(JSON.stringify(log, null, 2))}</pre></details>`,
});
ui.notifications.info(game.i18n.format("FISHUT.RemoveTolerance.Removed", { actor: actor.name, count: chosen.length }));
